[3] ## Shardlord (boss)
The Shardlord is the boss. It has 5000 health and 15 armor and appears on waves 20 and 40. When
its health drops below 25 percent it enrages and gains 50 percent more movement speed. If a
Shardlord leaks it costs 5 lives instead of 1.

[4] func _process(delta: float) -> void:
	if poison_time_left > 0.0:
		poison_time_left -= delta
		health -= int(4 * poison_stacks * delta)
		if poison_time_left <= 0.0:
			poison_stacks = 0

[2] func upgrade() -> bool:
	if level >= MAX_LEVEL:
		return false
	var cost := upgrade_cost()
	if not GameState.spend_gold(cost):
		return false
	level += 1
	total_invested += cost
	upgraded.emit(level)
	return true
